namespace Petal.App.Localization;

/// <summary>
/// Arabic interface text, keyed by the English string used in the code. Counted phrases
/// (looked up with <see cref="L.P"/> by their English plural) hold five forms separated by "|":
/// one, two, 3–10, 11–99, and 0 / 100+. "context:English" keys disambiguate words that Arabic
/// translates differently in different places. Petal and other product names stay in Latin script.
/// </summary>
