        ["With the AI model, DropWheel also understands requests worded freely. It runs on this PC."] = "مع نموذج الذكاء الاصطناعي يفهم DropWheel الطلبات المكتوبة بأي صياغة. يعمل النموذج على هذا الكمبيوتر.",
        ["Thinking…"] = "جارٍ التفكير…",
        ["DropWheel didn't find something it can do in that. Try naming the result: a format, a size, an app to send to, one PDF or a ZIP."] = "لم يجد DropWheel في طلبك شيئًا يستطيع فعله. جرّب أن تسمّي النتيجة: صيغة، أو حجمًا، أو تطبيقًا للإرسال، أو PDF واحدًا، أو ملف ZIP.",
        ["DropWheel didn't understand that yet. Try simpler words, or download the AI model below to ask any way you like."] = "لم يفهم DropWheel طلبك بعد. جرّب كلمات أبسط، أو نزّل نموذج الذكاء الاصطناعي أدناه لتسأل بالطريقة التي تريدها.",
        ["DropWheel will:"] = "سيقوم DropWheel بما يلي:",
