        ["To find photos and videos by what they show, DropWheel needs its picture models."] = "ليجد DropWheel الصور والفيديوهات بما تُظهره، يحتاج إلى نماذج الصور الخاصة به.",
        ["Enter opens the first result. Drag a result into any app."] = "يفتح Enter النتيجة الأولى. اسحب أي نتيجة إلى أي تطبيق.",
        ["Search by Meaning is off."] = "البحث بالمعنى متوقف.",
