        ["Looks like it"] = "يشبهه",
        ["Mentions it"] = "يذكره",
        ["{0} files in the index"] = "ملف واحد في الفهرس|ملفان في الفهرس|{0} ملفات في الفهرس|{0} ملفًا في الفهرس|{0} ملف في الفهرس",
        ["{0} waiting to be read"] = "ملف واحد بانتظار القراءة|ملفان بانتظار القراءة|{0} ملفات بانتظار القراءة|{0} ملفًا بانتظار القراءة|{0} ملف بانتظار القراءة",
        ["Find files by what they're about: the words in documents and screenshots, and what photos and videos show. DropWheel reads the folders below while the PC is idle; the index stays on this PC."] = "اعثر على الملفات بموضوعها: الكلمات في المستندات ولقطات الشاشة، وما تُظهره الصور والفيديوهات. يقرأ DropWheel المجلدات أدناه حين يكون الكمبيوتر خاملًا، ويبقى الفهرس على هذا الكمبيوتر.",
