        ["Gentle"] = "خفيف",
        ["Full"] = "كامل",
        ["Gentle leaves a little of the room's sound, so the voice stays natural. Full takes out all the noise it can."] = "«خفيف» يُبقي قليلًا من صوت المكان فيبقى الصوت طبيعيًا. «كامل» يزيل كل ما يستطيع من الضوضاء.",
        ["Made for speech: interviews, lectures, calls and videos. In a video only the sound changes."] = "مصممة للكلام: المقابلات والمحاضرات والمكالمات والفيديوهات. في الفيديو يتغيّر الصوت فقط.",
        ["Noise removed"] = "أُزيلت الضوضاء",
        ["Removing noise"] = "جارٍ إزالة الضوضاء",
        ["Split into"] = "التقسيم إلى",
        ["Vocals and music"] = "الغناء والموسيقى",
        ["Four parts"] = "أربعة أجزاء",
        ["Four parts: vocals, drums, bass and the other instruments, each in its own file."] = "أربعة أجزاء: الغناء والطبول والباص وبقية الآلات، كلٌّ في ملف مستقل.",
        ["Runs on this PC. A song of a few minutes takes a few minutes."] = "يعمل على هذا الكمبيوتر. الأغنية التي مدتها بضع دقائق تستغرق بضع دقائق.",
        ["Separate"] = "فصل",
        ["Separated"] = "تم الفصل",
        ["Separating"] = "جارٍ الفصل",
        ["English subtitles become Arabic, cue by cue, with their timing unchanged. Saved beside the original with “.ar” in the name, so players offer them as Arabic."] = "تتحول الترجمة الإنجليزية إلى العربية سطرًا بسطر دون تغيير توقيتها. تُحفظ بجانب الأصل وفي اسمها «" + Lrm + ".ar» فتعرضها المشغلات على أنها عربية.",
        ["For subtitles in another language, use Transcribe on the video with Arabic subtitles."] = "لترجمة من لغة أخرى، استخدم «تحويل الكلام إلى نص» على الفيديو واختر الترجمة العربية.",
        ["Translate"] = "ترجمة",
        ["Translated"] = "تمت الترجمة",
        ["Translating"] = "جارٍ الترجمة",
        ["Subtitles in"] = "لغة الترجمة",
        ["As spoken"] = "بلغة الكلام",
        ["In Arabic"] = "بالعربية",
        ["Start the Session"] = "ابدأ الجلسة",
        ["In English"] = "بالإنجليزية",
        ["PCs with DropWheel on the same network can send files with Send to PC. DropWheel asks every time, and saves them in Downloads\\DropWheel."] = "الأجهزة التي عليها DropWheel في الشبكة نفسها تستطيع إرسال ملفات إليك بـ «إرسال إلى جهاز». يسألك DropWheel كل مرة، ويحفظها في التنزيلات\\DropWheel.",
        ["Arabic"] = "العربية",
        ["Erase"] = "محو",
        ["Undo"] = "تراجع",
        ["Brush"] = "الفرشاة",
        ["Brush over what should go, then Erase. Brush a little beyond its edges."] = "مرّر الفرشاة على ما تريد إزالته ثم اضغط «محو». تجاوز حوافه قليلًا.",
        ["Save Copy"] = "حفظ نسخة",
