        // ---------- errors reported by the engines ----------
        ["Converting slides needs Microsoft PowerPoint or LibreOffice."] = "يتطلب تحويل العروض التقديمية Microsoft PowerPoint أو LibreOffice.",
        ["Could not measure the loudness of this file."] = "تعذّر قياس جهارة هذا الملف.",
        ["ExifTool isn't installed."] = "ExifTool غير مثبّت.",
        ["FFmpeg did not produce any output."] = "لم يُنتج FFmpeg أي مخرجات.",
        ["FFmpeg was not found. Install FFmpeg or place ffmpeg.exe in DropWheel's tools folder."] = "لم يُعثر على FFmpeg. ثبّت FFmpeg أو ضع ffmpeg.exe في مجلد أدوات DropWheel.",
        ["FFmpeg was not found."] = "لم يُعثر على FFmpeg.",
        ["FFprobe was not found. Install FFmpeg or place ffprobe.exe in DropWheel's tools folder."] = "لم يُعثر على FFprobe. ثبّت FFmpeg أو ضع ffprobe.exe في مجلد أدوات DropWheel.",
        ["HEIC output needs FFmpeg, which was not found."] = "يتطلب الإخراج بصيغة HEIC برنامج FFmpeg، ولم يُعثر عليه.",
        ["Saving HEIC needs FFmpeg with the libx265 encoder, which was not found."] = "يتطلب حفظ HEIC برنامج FFmpeg مع المرمّز libx265، ولم يُعثر عليه.",
        ["LibreOffice is not installed."] = "LibreOffice غير مثبّت.",
        ["No Windows OCR language is installed. Add one under Settings › Time & language › Language."] = "لا توجد لغة مثبّتة للتعرّف على النصوص في Windows. أضف لغة من الإعدادات › الوقت واللغة › اللغة.",
        ["Not an archive."] = "ليس ملف أرشيف.",
        ["The PDF has no pages."] = "لا يحتوي ملف PDF على صفحات.",
        ["A PDF needs at least one page"] = "يحتاج ملف PDF إلى صفحة واحدة على الأقل",
        ["The document has no pages."] = "لا يحتوي المستند على صفحات.",
        ["The audio is silent, so there is nothing to normalize."] = "الصوت صامت، فلا يوجد ما يمكن توحيده.",
        ["The end must be after the start."] = "يجب أن تكون النهاية بعد البداية.",
        ["The video's length is unknown, so it cannot be split."] = "طول الفيديو غير معروف، لذا لا يمكن تقسيمه.",
        ["This file has no video to turn into a GIF."] = "لا يحتوي هذا الملف على فيديو لتحويله إلى GIF.",
        ["Metadata can't be changed in this file type"] = "لا يمكن تغيير البيانات الوصفية في هذا النوع من الملفات",
        ["The EXIF data is too large to fit in a JPEG file."] = "بيانات EXIF أكبر من أن تتسع في ملف JPEG.",
        ["Image is too large for HEIC"] = "الصورة أكبر من أن تُحفظ بصيغة HEIC",
        ["Image is too large for a HEIC file"] = "الصورة أكبر من أن تُحفظ بصيغة HEIC",
        ["Unknown image format"] = "صيغة صورة غير معروفة",
        ["This file has no sound to transcribe."] = "لا يحتوي هذا الملف على صوت لتحويله إلى نص.",
        ["This video format can't hold a subtitle track. Choose “Burned in”, or save as MP4 or MKV."] = "لا تدعم صيغة هذا الفيديو مسار ترجمة. اختر «مدمجة في الصورة» أو احفظه بصيغة MP4 أو MKV.",
        ["The speech model isn't downloaded yet."] = "لم يُنزَّل نموذج الكلام بعد.",
        ["The background removal model isn't downloaded yet."] = "لم يُنزَّل نموذج إزالة الخلفية بعد.",
        ["The update feed couldn't be reached."] = "تعذّر الوصول إلى مصدر التحديثات.",
        ["The update feed isn't valid."] = "مصدر التحديثات غير صالح.",
        ["The update feed points to an address that isn't secure."] = "يشير مصدر التحديثات إلى عنوان غير آمن.",
        ["Check for the update first."] = "تحقّق من وجود التحديث أولًا.",
        ["The downloaded update didn't match its checksum, so it was thrown away."] = "لم يطابق التحديث الذي نُزِّل مجموع التحقق الخاص به، لذا حُذف.",
        ["The update couldn't be downloaded."] = "تعذّر تنزيل التحديث.",
        ["Update feeds must use https://."] = "يجب أن يستخدم مصدر التحديثات https://.",
        ["The update address isn't valid."] = "عنوان التحديثات غير صالح.",
        ["The photo has no pixels."] = "لا تحتوي الصورة على بكسلات.",
        ["The picture has no pixels."] = "لا تحتوي الصورة على بكسلات.",
        ["The page's corners don't make a quadrilateral."] = "زوايا الصفحة لا تشكّل شكلًا رباعيًا.",
        ["The eraser model isn't downloaded yet."] = "لم يُنزَّل نموذج المحو بعد.",
        ["There's no text to read aloud."] = "لا يوجد نص للقراءة بصوت عالٍ.",
        ["The voice changed its audio format partway through."] = "غيّر الصوت صيغته في منتصف القراءة.",
        ["Windows didn't return speech audio."] = "لم يُرجع Windows صوت الكلام.",
        ["Windows returned speech in a format DropWheel doesn't expect."] = "أرجع Windows الكلام بصيغة لا يتوقعها DropWheel.",
        ["The natural voices aren't downloaded yet."] = "لم تُنزَّل الأصوات الطبيعية بعد.",
        ["Piper didn't start."] = "لم يبدأ Piper.",
        ["The noise removal model isn't downloaded yet."] = "لم يُنزَّل نموذج إزالة الضوضاء بعد.",
        ["The separation model isn't downloaded yet."] = "لم يُنزَّل نموذج الفصل بعد.",
        ["This file has no sound to separate."] = "لا يحتوي هذا الملف على صوت لفصله.",
        ["The sound is too short to separate."] = "الصوت أقصر من أن يُفصل.",
        ["The AI model isn't downloaded yet."] = "لم يُنزَّل نموذج الذكاء الاصطناعي بعد.",
        ["The AI model didn't start."] = "لم يبدأ نموذج الذكاء الاصطناعي.",
        ["The AI model stopped unexpectedly."] = "توقف نموذج الذكاء الاصطناعي على نحو غير متوقع.",
        ["The program didn't start."] = "لم يبدأ البرنامج.",
        ["The program finished without making its result."] = "انتهى البرنامج دون أن يُنتج نتيجته.",
        ["This recipe has no steps yet."] = "لا تحتوي هذه الوصفة على خطوات بعد.",
        ["The background removal model isn't downloaded yet. Open Remove Background once to get it."] = "لم يُنزَّل نموذج إزالة الخلفية بعد. افتح «إزالة الخلفية» مرة واحدة للحصول عليه.",
        ["DropWheel can't clean this kind of file."] = "لا يستطيع DropWheel تنظيف هذا النوع من الملفات.",
        ["The translation model isn't downloaded yet."] = "لم يُنزَّل نموذج الترجمة بعد.",
        ["The tokenizer model is damaged."] = "نموذج تقطيع النص تالف.",
        ["This Photoshop file version isn't supported."] = "إصدار ملف فوتوشوب هذا غير مدعوم.",
        ["The Photoshop file ends early."] = "ملف فوتوشوب ناقص.",
        ["The layers of this file couldn't be matched to their names."] = "تعذّر مطابقة طبقات هذا الملف مع أسمائها.",
        ["This file has no layers with pixels."] = "لا يحتوي هذا الملف على طبقات بها بكسلات.",
        ["Every layer with pixels is hidden. Include hidden layers to save them."] = "كل الطبقات التي بها بكسلات مخفية. فعّل تضمين الطبقات المخفية لحفظها.",
        ["This file has no Photoshop history to remove."] = "لا يحتوي هذا الملف على سجل فوتوشوب لإزالته.",
        ["Drawing EPS files needs Ghostscript, which is free. Install it from ghostscript.com and try again, or use Save Preview for the small picture inside the file."] = "رسم ملفات EPS يحتاج إلى Ghostscript، وهو مجاني. ثبّته من ghostscript.com ثم حاول مجددًا، أو استخدم «حفظ المعاينة» للصورة الصغيرة الموجودة داخل الملف.",
        ["Illustrator files need the PDF engine."] = "تحتاج ملفات Illustrator إلى محرك PDF.",
        ["DropWheel can't read this kind of file."] = "لا يستطيع DropWheel قراءة هذا النوع من الملفات.",
        ["This isn't an After Effects project."] = "هذا ليس مشروع After Effects.",
        ["This swatch file has no colours."] = "لا يحتوي ملف الألوان هذا على ألوان.",
