        ["Include files in subfolders"] = "تضمين ملفات المجلدات الفرعية",
        ["Sorts the files of “{0}” into folders. Nothing is copied or deleted, and History can put everything back."] = "يرتّب ملفات «{0}» في مجلدات. لا يُنسخ شيء ولا يُحذف، ويمكن إرجاع كل شيء من السجل.",
        ["Sort"] = "الترتيب",
        ["Invoices are recognised by reading the text of PDFs and photos, which takes a little longer."] = "تُعرف الفواتير بقراءة نص ملفات PDF والصور، وهذا يستغرق وقتًا أطول قليلًا.",
        ["Organize"] = "ترتيب",
        ["There are no files to sort."] = "لا توجد ملفات لترتيبها.",
        ["{0} files go into folders for their year and month (2024 › 2024-07): photos by the day they were taken, the rest by the day they last changed."] = "يذهب ملف واحد إلى مجلد سنته وشهره (2024 › 2024-07): الصور بيوم التقاطها، والباقي بيوم آخر تعديل.|يذهب ملفان إلى مجلدات سنتهما وشهرهما (2024 › 2024-07): الصور بيوم التقاطها، والباقي بيوم آخر تعديل.|تذهب {0} ملفات إلى مجلدات سنواتها وأشهرها (2024 › 2024-07): الصور بيوم التقاطها، والباقي بيوم آخر تعديل.|يذهب {0} ملفًا إلى مجلدات سنواتها وأشهرها (2024 › 2024-07): الصور بيوم التقاطها، والباقي بيوم آخر تعديل.|يذهب {0} ملف إلى مجلدات سنواتها وأشهرها (2024 › 2024-07): الصور بيوم التقاطها، والباقي بيوم آخر تعديل.",
        ["{0} other files stay where they are"] = "يبقى ملف آخر مكانه|يبقى ملفان آخران مكانهما|تبقى {0} ملفات أخرى مكانها|يبقى {0} ملفًا آخر مكانه|يبقى {0} ملف آخر مكانه",
