        ["The PC's sound or the microphone"] = "صوت الجهاز أو الميكروفون",
        ["The apps open now and where their windows are. Open the workspace later and DropWheel opens what isn't running and puts every window back."] = "التطبيقات المفتوحة الآن وأماكن نوافذها. افتح مساحة العمل لاحقًا فيفتح DropWheel ما ليس مفتوحًا ويعيد كل نافذة إلى مكانها.",
        ["The camera glides in where you click and follows the pointer, the pointer is smoothed and larger, and the video sits on a background with rounded corners."] = "تقترب الكاميرا بنعومة حيث تنقر وتتبع المؤشر، ويصبح المؤشر أنعم وأكبر، ويوضع الفيديو على خلفية بزوايا مستديرة.",
        ["The captions are translated into Arabic by a translation model on this PC. Until it is here, they show what was said."] = "تُترجم الكلمات إلى العربية بنموذج ترجمة على هذا الجهاز. وحتى يصل، تُعرض كما قيلت.",
        ["The command palette, snippets, workspaces, and receiving files from other PCs."] = "لوحة الأوامر، والمقتطفات، ومساحات العمل، واستقبال الملفات من الأجهزة الأخرى.",
        ["The connection broke off. Try again."] = "انقطع الاتصال. حاول مجددًا.",
        ["The other PC needs DropWheel with “Let other PCs send me files” on (Settings › Work & Sharing). It asks before saving anything, and the files go straight across your network."] = "يحتاج الجهاز الآخر إلى DropWheel مع تفعيل «السماح للأجهزة الأخرى بإرسال ملفات إليّ» (الإعدادات › العمل والمشاركة). يسأل قبل حفظ أي شيء، وتنتقل الملفات مباشرة عبر شبكتك.",
        ["The palette, screenshots, the colour picker, the ruler, the clipboard history, sums and windows side by side."] = "لوحة الأوامر، ولقطات الشاشة، والتقاط الألوان، والمسطرة، وسجل الحافظة، والحساب، والنوافذ جنبًا إلى جنب.",
        ["The recording couldn't be polished; it is saved as it was."] = "تعذّر تحسين التسجيل؛ حُفظ كما هو.",
        ["The sharpest"] = "الأوضح",
        ["The sound couldn't be listened to."] = "تعذّر الاستماع إلى الصوت.",
        ["The speech model couldn't be loaded."] = "تعذّر تحميل نموذج الكلام.",
        ["The {0} wheel"] = "عجلة {0}",
        ["These apps go down to the taskbar whenever they come to the front, until the session ends:"] = "هذه التطبيقات تنزل إلى شريط المهام كلما ظهرت في الواجهة، حتى تنتهي الجلسة:",
        ["They are saved in {0}."] = "تُحفظ في {0}.",
