        ["Type an abbreviation in any app and it becomes its text. Start abbreviations with a sign such as ; so they don't turn up in ordinary words. They work whichever keyboard language is on."] = "اكتب الاختصار في أي تطبيق فيتحول إلى نصه. ابدأ الاختصارات بعلامة مثل ; حتى لا تظهر داخل الكلمات العادية. تعمل أيًّا كانت لغة لوحة المفاتيح.",
        ["Type how many minutes"] = "اكتب عدد الدقائق",
        ["Type what you want: any action, a petal for the selected files, an app, a file, a sum."] = "اكتب ما تريد: أي إجراء، أو بتلة للملفات المحددة، أو تطبيقًا، أو ملفًا، أو عملية حسابية.",
