        ["None of your indexed files mention it."] = "لا يذكره أي ملف من ملفاتك المفهرسة.",
        ["Answer"] = "الجواب",
        ["From what your files say, read on this PC. Check the source before you rely on it."] = "مما تقوله ملفاتك، قُرئ على هذا الجهاز. تحقّق من المصدر قبل أن تعتمد عليه.",
