        ["These passages mention it:"] = "هذه المقاطع تذكره:",
        ["With the AI model on this PC, DropWheel answers in a sentence."] = "مع نموذج الذكاء الاصطناعي على هذا الجهاز، يجيب DropWheel بجملة.",
