        ["Another program may be keeping them from DropWheel, or Windows stopped it after a long freeze. Closing and opening DropWheel again usually brings them back."] = "ربما يحجبها برنامج آخر عن DropWheel، أو أوقفه Windows بعد تجمّد طويل. إغلاق DropWheel وفتحه من جديد يعيدها عادةً.",
        ["Every shortcut works"] = "كل الاختصارات تعمل",
