        ["Choose another shortcut in Settings, or close the program that uses it."] = "اختر اختصارًا آخر من الإعدادات، أو أغلق البرنامج الذي يستخدمه.",
        ["Open Settings"] = "فتح الإعدادات",
        ["Helper programs"] = "البرامج المساعدة",
