        ["Missing or not starting: {0}"] = "مفقود أو لا يبدأ: {0}",
        ["Video, sound and photo details need them. Installing DropWheel again puts them back."] = "يحتاج إليها الفيديو والصوت وتفاصيل الصور. إعادة تثبيت DropWheel تعيدها.",
