        ["Not receiving files from other PCs"] = "لا يستقبل الملفات من أجهزة أخرى",
        ["Connections"] = "الاتصالات",
        ["DropWheel goes online only to download a model you ask for, to look for updates when an address is set, or to fetch today's exchange rates when you convert a currency."] = "لا يتصل DropWheel بالإنترنت إلا لتنزيل نموذج تطلبه، أو للبحث عن تحديثات حين يُحدَّد عنوان، أو لجلب أسعار الصرف لليوم حين تحوّل عملة.",
        ["DropWheel looked itself over. Nothing is changed unless you choose a fix."] = "فحص DropWheel نفسه. لا يتغير شيء ما لم تختر إصلاحًا.",
        ["Save a Report…"] = "حفظ تقرير…",
        ["Check Again"] = "الفحص مجددًا",
        ["DropWheel couldn't finish looking"] = "تعذّر على DropWheel إكمال الفحص",
