        ["A sentence"] = "جملة",
        ["A paragraph"] = "فقرة",
        ["Save in the Picture"] = "حفظ في الصورة",
        ["Writes the description into the picture's details, where photo apps and websites can read it. The picture itself doesn't change."] = "يكتب الوصف في تفاصيل الصورة، حيث تقرؤه تطبيقات الصور والمواقع. الصورة نفسها لا تتغير.",
        ["Written on this PC by a small AI model; check it before you publish it."] = "كتبه نموذج ذكاء اصطناعي صغير على هذا الجهاز؛ راجعه قبل نشره.",
        ["Describing pictures needs the picture model, downloaded once (about 570 MB)."] = "يحتاج وصف الصور إلى نموذج الصور، يُنزَّل مرة واحدة (نحو 570 ميغابايت).",
        ["Looking at the picture…"] = "يتأمل الصورة…",
        ["The description is in English. Download the translation model to have it in Arabic."] = "الوصف بالإنجليزية. نزّل نموذج الترجمة لتحصل عليه بالعربية.",
        ["The picture couldn't be described."] = "تعذّر وصف الصورة.",
        ["You can change the words before copying."] = "يمكنك تعديل الكلمات قبل النسخ.",
