        ["Follow"] = "تتبّع",
        ["Whole picture"] = "الصورة كاملة",
        ["Tall window"] = "الإطار الطولي",
        ["Make Vertical"] = "اجعله عموديًا",
        ["This video is already tall"] = "هذا الفيديو طولي أصلًا",
        ["The tall window follows the person, found by the background model on this PC, and glides rather than jumps."] = "يتتبّع الإطار الطولي الشخص الذي يجده نموذج الخلفية على هذا الجهاز، وينزلق بنعومة بدل أن يقفز.",
        ["The tall window follows what moves. With the background model it follows people more surely."] = "يتتبّع الإطار الطولي ما يتحرك. ومع نموذج الخلفية يتتبّع الأشخاص بدقة أكبر.",
        ["The middle of the picture, from top to bottom."] = "وسط الصورة، من أعلاها إلى أسفلها.",
        ["All of the picture, over a blurred, enlarged copy of itself."] = "الصورة كلها، فوق نسخة مكبّرة ومموّهة منها.",
