        ["{0} lines to dub"] = "جملة واحدة للدبلجة|جملتان للدبلجة|{0} جمل للدبلجة|{0} جملة للدبلجة|{0} جملة للدبلجة",
        ["Windows can't play this video here; the dub is made all the same."] = "لا يستطيع Windows تشغيل هذا الفيديو هنا، لكن الدبلجة تُصنع كالمعتاد.",
        ["This video is already in Arabic."] = "هذا الفيديو بالعربية أصلًا.",
        ["This video is already in English."] = "هذا الفيديو بالإنجليزية أصلًا.",
        ["Dub works on speech in Arabic or English."] = "تعمل الدبلجة على الكلام بالعربية أو الإنجليزية.",
        ["The voice model isn't downloaded yet."] = "لم يُنزَّل نموذج الصوت بعد.",
        ["Each line is said again in the other language, in the voice of the person who said it. The music is taken out; every other sound stays."] = "تُقال كل جملة من جديد باللغة الأخرى، بصوت من قالها نفسه. وتُحذف الموسيقى وتبقى كل الأصوات الأخرى.",
        ["Separating the voices…"] = "جارٍ عزل أصوات المتكلمين…",
        ["Edit by Text"] = "تعديل بالنص",
        ["EDIT BY TEXT"] = "تعديل بالنص",
        ["What was said is written down, each word with its time. Take words out of the text and they are cut out of the picture and the sound."] = "يُكتب ما قيل مع توقيت كل كلمة. احذف كلمات من النص فتُقصّ من الصورة والصوت معًا.",
        ["It all happens on this PC; nothing is uploaded. A recording heard once opens again at once."] = "يجري كل شيء على هذا الحاسوب ولا يُرفع أي شيء. والتسجيل الذي سُمع مرة يُفتح بعدها فورًا.",
        ["Play the edit (Space)"] = "تشغيل التعديل (مسافة)",
        ["Take the words selected out, or put them back (Delete)"] = "حذف الكلمات المحددة أو إرجاعها (Delete)",
        ["Hesitations such as “um” and “uh”, a word said twice in a row, and the sounds between words that weren't words"] = "التردد مثل «إمم» و«آآ»، والكلمة المكررة مرتين متتاليتين، والأصوات التي بين الكلمات وليست كلمات",
        ["Pauses longer than {0} s are shortened to {1} s"] = "تُقصَّر فترات الصمت الأطول من {0} ث إلى {1} ث",
        ["Find words (Ctrl+F)"] = "ابحث عن كلمات (Ctrl+F)",
        ["Take them out"] = "احذفها كلها",
        ["Select words and press Delete to take them out, and again to put them back. Space plays the edit from the cursor."] = "حدّد كلمات واضغط Delete لحذفها، واضغطه مرة أخرى لإرجاعها. ويشغّل مفتاح المسافة التعديل من موضع المؤشر.",
        ["This file has no sound to hear."] = "لا يحتوي هذا الملف على صوت يمكن الاستماع إليه.",
        ["Heard before: the words are shown at once."] = "سُمع من قبل: تظهر الكلمات فورًا.",
        ["Show the Words"] = "اعرض الكلمات",
        ["Listening…"] = "جارٍ الاستماع…",
        ["Listening to the recording…"] = "جارٍ الاستماع إلى التسجيل…",
        ["[sound]"] = "[صوت]",
        ["Play from here"] = "تشغيل من هنا",
        ["Put everything back"] = "إرجاع كل شيء",
