        ["Put back"] = "إرجاع",
        ["Take out"] = "حذف",
        ["Take out {0} fillers"] = "حذف كلمة حشو|حذف كلمتَي حشو|حذف {0} كلمات حشو|حذف {0} كلمة حشو|حذف {0} كلمة حشو",
        ["No fillers left"] = "لا حشو متبقٍّ",
        ["Shorten {0} long pauses"] = "تقصير فترة صمت طويلة|تقصير فترتَي صمت طويلتين|تقصير {0} فترات صمت طويلة|تقصير {0} فترة صمت طويلة|تقصير {0} فترة صمت طويلة",
        ["No long pauses left"] = "لا فترات صمت طويلة متبقية",
