        ["Ask a File"] = "اسأل الملف",
        ["ASK FILE"] = "اسأل الملف",
        ["Ask anything about it: the answer comes from its own words, with where it says so. All on this PC."] = "اسأل عنه ما شئت: تأتي الإجابة من كلماته هو، مع المكان الذي يقول فيه ذلك. وكل ذلك على هذا الحاسوب.",
        ["Read once and kept, so asking again later is quick."] = "يُقرأ مرة واحدة ويُحفظ، فتكون الأسئلة اللاحقة سريعة.",
        ["Ask your first question below. For example: what does it say about prices? Where are the dates? What was decided?"] = "اكتب سؤالك الأول في الأسفل. مثلًا: ماذا يقول عن الأسعار؟ أين التواريخ؟ ما الذي تقرر؟",
        ["Written answers come from an AI model on this PC. Until it is here you see the parts of the file that speak to your question."] = "تأتي الإجابات المكتوبة من نموذج ذكاء اصطناعي على هذا الحاسوب. وإلى أن يُنزَّل ترى أجزاء الملف التي تتحدث عن سؤالك.",
        ["Ask a question about this file"] = "اسأل سؤالًا عن هذا الملف",
