        ["Download a model and run it on this PC, or use your own API key from Gemini, ChatGPT or Claude at your own cost."] = "نزّل نموذجًا وشغّله على هذا الحاسوب، أو استخدم مفتاح API الخاص بك من Gemini أو ChatGPT أو Claude على نفقتك.",
        ["What does each job"] = "ما الذي ينفّذ كل مهمة",
        ["Writing and answers"] = "الكتابة والإجابات",
        ["Describing pictures"] = "وصف الصور",
        ["This PC needs a model downloaded once, and nothing leaves it. A cloud model needs no download, but what the job works on goes to that company, and the provider bills your key."] = "هذا الحاسوب يحتاج إلى تنزيل نموذج مرة واحدة ولا يخرج منه شيء. أما النموذج السحابي فلا يحتاج إلى تنزيل، لكن ما تعمل عليه المهمة يُرسل إلى تلك الشركة، وتُحتسب التكلفة على مفتاحك.",
        ["This PC"] = "هذا الحاسوب",
