        ["Save Key"] = "حفظ المفتاح",
        ["A key is saved, encrypted for this Windows user."] = "المفتاح محفوظ ومشفَّر لمستخدم Windows هذا.",
        ["Checking the key…"] = "جارٍ فحص المفتاح…",
        ["The key works: {0} models on offer."] = "المفتاح يعمل: {0} من النماذج متاحة.",
        ["Add your API key in Settings › AI Models first."] = "أضف مفتاح API أولًا من الإعدادات › نماذج الذكاء الاصطناعي.",
        ["The cloud model couldn't be reached. Check the internet connection."] = "تعذّر الوصول إلى النموذج السحابي. تحقق من الاتصال بالإنترنت.",
        ["The API key was refused. Check it in Settings › AI Models."] = "رُفض مفتاح API. تحقق منه في الإعدادات › نماذج الذكاء الاصطناعي.",
        ["This model isn't available with your key. Choose another in Settings › AI Models."] = "هذا النموذج غير متاح بمفتاحك. اختر غيره من الإعدادات › نماذج الذكاء الاصطناعي.",
        ["The provider says the key is out of credit or over its limit. Try again later, or check your account."] = "يقول المزوّد إن رصيد المفتاح نفد أو تجاوز حدّه. حاول لاحقًا أو راجع حسابك.",
        ["The provider's service is having trouble. Try again later."] = "خدمة المزوّد تواجه مشكلة. حاول لاحقًا.",
        ["The cloud model declined this request."] = "رفض النموذج السحابي هذا الطلب.",
        ["On this PC"] = "على هذا الحاسوب",
        ["With your own API key"] = "بمفتاح API الخاص بك",
        ["Use This PC"] = "استخدام هذا الحاسوب",
