        ["Language, theme, colours, and how the wheel looks and sounds."] = "اللغة والمظهر والألوان، وشكل العجلة وأصواتها.",
        ["What comes first on the wheels."] = "ما يأتي أولًا في العجلات.",
        ["Several steps in one petal, folders that convert by themselves, and petals of your own."] = "عدة خطوات في بتلة واحدة، ومجلدات تحوّل من تلقاء نفسها، وبتلات من صنعك.",
        ["Models on this PC, your own API keys, and searching by meaning."] = "النماذج على هذا الحاسوب، ومفاتيح API الخاصة بك، والبحث بالمعنى.",
        ["Where results go, and their quality."] = "أين تذهب النتائج، وجودتها.",
        ["Starting with Windows, helper programs, backup and updates."] = "البدء مع Windows، والبرامج المساعدة، والنسخ الاحتياطي، والتحديثات.",
        ["A short look at the wheel."] = "نظرة قصيرة على العجلة.",
        ["Every tool explained, and your questions answered."] = "شرح كل أداة، والإجابة عن أسئلتك.",
        ["Try the wheel on a sample file."] = "جرّب العجلة على ملف تجريبي.",
        ["A walk through these pages."] = "جولة في هذه الصفحات.",
        ["From a link or any text."] = "من رابط أو أي نص.",
        ["What DropWheel made, and undoing it."] = "ما صنعه DropWheel، والتراجع عنه.",
        ["Language & Colours"] = "اللغة والألوان",
        ["The Wheel's Look"] = "شكل العجلة",
        ["Sounds & Hints"] = "الأصوات والتلميحات",
        ["Saved Files"] = "الملفات المحفوظة",
        ["Where each thing DropWheel makes is saved. Open any folder from here, or copy its path."] = "أين يُحفظ كل ما يصنعه DropWheel. افتح أي مجلد من هنا، أو انسخ مساره.",
        ["What You Make"] = "ما تصنعه أنت",
        ["DropWheel's Own Files"] = "ملفات DropWheel نفسه",
        ["Beside the original file (you can choose a folder on the Conversions page)."] = "بجانب الملف الأصلي (يمكنك اختيار مجلد من صفحة التحويلات).",
        ["Conversions and tools"] = "التحويلات والأدوات",
        ["What the wheel and the tools make from your files."] = "ما تصنعه العجلة والأدوات من ملفاتك.",
        ["Screenshots, scrolling captures, drawings on the screen, and pictures from the clipboard."] = "لقطات الشاشة، واللقطات الطويلة، والرسم على الشاشة، وصور الحافظة.",
        ["Screen recordings"] = "تسجيلات الشاشة",
        ["Screen recordings, and what the Recording Studio saves from them."] = "تسجيلات الشاشة، وما يحفظه استوديو التسجيل منها.",
        ["Meeting notes"] = "ملاحظات الاجتماعات",
        ["The notes and summaries of your meetings."] = "ملاحظات اجتماعاتك وملخصاتها.",
        ["Step guides"] = "أدلة الخطوات",
        ["The guides made by recording your steps."] = "الأدلة المصنوعة بتسجيل خطواتك.",
        ["Pages scanned with your phone, as PDF files."] = "الصفحات الممسوحة بهاتفك، كملفات PDF.",
        ["Tables from the screen"] = "الجداول من الشاشة",
        ["Excel files of the tables read from the screen."] = "ملفات Excel للجداول المقروءة من الشاشة.",
        ["Text from the clipboard"] = "نص من الحافظة",
        ["Copied text kept as a file by the clipboard's wheel."] = "النص المنسوخ المحفوظ كملف من عجلة الحافظة.",
        ["Files from your phone"] = "ملفات من هاتفك",
        ["What your phone sends to this PC, and files dragged out of other programs."] = "ما يرسله هاتفك إلى هذا الحاسوب، والملفات المسحوبة من برامج أخرى.",
        ["Files from other PCs"] = "ملفات من حواسيب أخرى",
        ["What other PCs send with Send to PC."] = "ما ترسله الحواسيب الأخرى عبر الإرسال إلى حاسوب.",
        ["What arrives in {0} is converted into here."] = "ما يصل إلى {0} يُحوَّل إلى هنا.",
        ["The models you downloaded."] = "النماذج التي نزّلتها.",
        ["Recording Studio projects"] = "مشاريع استوديو التسجيل",
        ["Cinematic recordings before they are saved as videos."] = "التسجيلات السينمائية قبل حفظها كفيديو.",
        ["Your settings, wheels, petals and clipboard history. API keys are kept here too, encrypted."] = "إعداداتك وعجلاتك وبتلاتك وسجل الحافظة. وتُحفظ هنا مفاتيح API أيضًا، مشفّرة.",
        ["Prepared videos"] = "الفيديوهات المجهّزة",
        ["What Dub, Make Shorts, Edit by Text and Ask a File keep, so a file opens again at once."] = "ما تحتفظ به الدبلجة وصنع المقاطع والتحرير بالنص واسأل ملفًا، ليُفتح الملف فورًا مرة أخرى.",
        ["Activity log"] = "سجل النشاط",
        ["What DropWheel did, for finding out what went wrong."] = "ما فعله DropWheel، لمعرفة ما حدث عند وقوع خطأ.",
        ["Downloaded updates"] = "التحديثات المنزّلة",
        ["Installers waiting to run."] = "برامج تثبيت تنتظر التشغيل.",
        ["Keys & Behaviour"] = "المفاتيح والسلوك",
        ["What opens the wheel, and how it behaves."] = "ما يفتح العجلة، وكيف تتصرف.",
        ["Your wheels, and more to add from the gallery beside them."] = "عجلاتك، والمزيد لتضيفه من المعرض بجانبها.",
        ["Ready-Made Wheels"] = "عجلات جاهزة",
        ["For Apps and Work"] = "للتطبيقات والعمل",
        ["Find a wheel"] = "ابحث عن عجلة",
        ["No wheel matches."] = "لا توجد عجلة مطابقة.",
        ["Add {0}"] = "إضافة {0}",
        ["Change any folder: new files go there, and what is already saved stays where it is."] = "غيّر أي مجلد: تذهب الملفات الجديدة إليه، ويبقى ما حُفظ سابقًا في مكانه.",
        ["Change Folder…"] = "تغيير المجلد…",
        ["Back to the Usual Folder"] = "العودة إلى المجلد المعتاد",
        ["Save {0} in"] = "حفظ {0} في",
        ["One model translates from any language into any other."] = "يترجم نموذج واحد من أي لغة إلى أي لغة أخرى.",
        ["Into {0}"] = "إلى {0}",
        ["This language's translation model isn't here yet. Download it or use your key, then prepare again: what was heard is kept."] = "نموذج ترجمة هذه اللغة غير موجود بعد. نزّله أو استخدم مفتاحك، ثم جهّز مرة أخرى: ما سُمع محفوظ.",
        ["The translation model isn't downloaded yet. Download it or use your key."] = "نموذج الترجمة لم يُنزَّل بعد. نزّله أو استخدم مفتاحك.",
        ["A quicker model keeps the captions up with the speaker. Until it is here, the larger one translates them, a little behind."] = "نموذج أسرع يُبقي الترجمة مواكبة للمتحدث. وإلى أن يتوفر، يترجمها النموذج الأكبر متأخرًا قليلًا.",
        ["Use My API Key"] = "استخدام مفتاحي",
        ["Save and Use"] = "حفظ واستخدام",
        ["Use {0}"] = "استخدام {0}",
        ["Your API key"] = "مفتاح API الخاص بك",
        ["Gemini, ChatGPT or Claude. Nothing to download. What this job works on goes to that company, and it bills your key."] = "Gemini أو ChatGPT أو Claude. لا شيء يُنزَّل. يذهب ما تعمل عليه هذه المهمة إلى تلك الشركة، وهي التي تحاسب مفتاحك.",
        ["Translating with {0}, on your own key…"] = "جارٍ الترجمة عبر {0} بمفتاحك…",
        ["Translated by {0}, on your own key."] = "ترجمها {0} بمفتاحك.",
        ["The text goes to {0}, on your own API key."] = "يُرسل النص إلى {0} بمفتاح API الخاص بك.",
        ["The selected text, translated into your language."] = "النص المحدد مترجمًا إلى لغتك.",
        ["Captions for any video, call or lesson, translated as they come."] = "ترجمة مرئية لأي فيديو أو مكالمة أو درس، تُترجم فور ظهورها.",
        ["Translate into"] = "الترجمة إلى",
        ["The translation, the original, or both"] = "الترجمة أو الأصل أو كلاهما",
        ["Translation Model"] = "نموذج الترجمة",
        ["The captions are translated by a model on this PC, downloaded once. Until it is here, they show what was said."] = "تُترجم الكلمات بنموذج على هذا الحاسوب يُنزَّل مرة واحدة. وحتى يصل، تعرض ما قيل.",
        ["From the PC's sound or the microphone (a button on the captions switches). A translation model downloads the first time it is needed."] = "من صوت الحاسوب أو الميكروفون (زر على الشريط يبدّل بينهما). يُنزَّل نموذج الترجمة أول مرة يلزم فيها.",
        ["Translate Subtitles"] = "ترجمة الترجمات المرئية",
        ["The subtitles are translated cue by cue, with their timing unchanged. Saved beside the original with the language in the name, so players offer them."] = "تُترجم الترجمات المرئية مقطعًا مقطعًا مع بقاء توقيتها. تُحفظ بجانب الأصل وفي اسمها اللغة، لتعرضها المشغّلات.",
        ["From"] = "من",
        ["Dub into"] = "الدبلجة إلى",
        ["This video is already in that language."] = "هذا الفيديو بتلك اللغة أصلًا.",
        ["Dub doesn't work on this language yet."] = "الدبلجة لا تعمل بهذه اللغة بعد.",
        ["DropWheel goes online only to download a model you ask for, to use a cloud model you chose with your own key, to look for updates when an address is set, or to fetch today's exchange rates when you convert a currency."] = "لا يتصل DropWheel بالإنترنت إلا لتنزيل نموذج تطلبه، أو لاستخدام نموذج سحابي اخترته بمفتاحك، أو للبحث عن تحديثات إذا حُدّد عنوان لها، أو لجلب أسعار الصرف عند تحويل عملة.",
        ["DropWheel uses these programs when they're installed, on this PC."] = "يستخدم DropWheel هذه البرامج عند تثبيتها، على هذا الحاسوب.",
        ["Into"] = "إلى",
        ["Model"] = "النموذج",
        ["Translate Document"] = "ترجمة مستند",
        ["A new file is saved beside the original, with its formatting kept and the language in its name."] = "يُحفظ ملف جديد بجانب الأصلي، بتنسيقه نفسه واسم اللغة في اسمه.",
        ["It runs on this PC: the file doesn't leave it."] = "يعمل على هذا الجهاز: لا يغادره الملف.",
        ["The file is already in this language."] = "الملف بهذه اللغة أصلًا.",
        ["This file has no text to translate."] = "لا يحتوي هذا الملف على نص لترجمته.",
        ["This kind of file can't be translated."] = "لا يمكن ترجمة هذا النوع من الملفات.",
        ["The translation came back incomplete."] = "عادت الترجمة ناقصة.",
        ["The document has no main part."] = "لا يحتوي المستند على جزء رئيسي.",
        ["The presentation has no slides."] = "لا يحتوي العرض التقديمي على شرائح.",
        ["The workbook has no sheets."] = "لا يحتوي المصنف على أوراق.",
        ["Edit PDF"] = "تحرير PDF",
        ["Select and move"] = "تحديد وتحريك",
        ["Write text"] = "كتابة نص",
        ["Today's date"] = "تاريخ اليوم",
        ["Tick"] = "علامة صح",
        ["Cross"] = "علامة خطأ",
        ["Dot"] = "نقطة",
        ["Edit the PDF's text"] = "تحرير نص ملف PDF",
        ["Highlight"] = "تمييز",
        ["Strike out"] = "شطب",
        ["Comment"] = "تعليق",
        ["Line"] = "خط",
        ["Whiteout"] = "طمس بالأبيض",
        ["Place a picture"] = "وضع صورة",
        ["Redact"] = "حجب",
        ["Fit the width"] = "ملاءمة العرض",
        ["Thickness"] = "السُمك",
        ["Box"] = "مربع",
        ["Words"] = "كلمات",
        ["Find and mark"] = "بحث وتعليم",
        ["Find private details"] = "البحث عن التفاصيل الخاصة",
        ["A word or phrase to redact on all pages"] = "كلمة أو عبارة تُحجب في كل الصفحات",
        ["E-mail addresses, phone numbers, card numbers, IBANs, IP addresses and passwords; scanned pages are read too."] = "عناوين البريد وأرقام الهواتف والبطاقات وأرقام IBAN وعناوين IP وكلمات المرور؛ وتُقرأ الصفحات الممسوحة ضوئيًا أيضًا.",
        ["Flatten"] = "تسطيح",
        ["Burn fields and annotations into the pages, so they can't be changed."] = "دمج الحقول والتعليقات في الصفحات، فلا يمكن تغييرها.",
        ["Remove the file's hidden details"] = "إزالة تفاصيل الملف المخفية",
        ["Author, dates, XMP, attachments and scripts leave the file with what is redacted."] = "يخرج المؤلف والتواريخ وXMP والمرفقات والبرامج النصية من الملف مع ما يُحجب.",
        ["Click an item to select it, drag to move it, drag its corners to resize. Click text to edit it."] = "انقر عنصرًا لتحديده، واسحبه لتحريكه، واسحب زواياه لتغيير حجمه. انقر النص لتحريره.",
        ["Click where the text goes, then type."] = "انقر حيث يوضع النص، ثم اكتب.",
        ["Click to stamp today's date."] = "انقر لوضع تاريخ اليوم.",
        ["Click to drop a tick."] = "انقر لوضع علامة صح.",
        ["Click to drop a cross."] = "انقر لوضع علامة خطأ.",
        ["Click to drop a dot."] = "انقر لوضع نقطة.",
        ["Click a line of the PDF's text to type it again."] = "انقر سطرًا من نص الملف لتكتبه من جديد.",
        ["Drag across words to highlight them."] = "اسحب عبر الكلمات لتمييزها.",
        ["Drag across words to underline them."] = "اسحب عبر الكلمات لتسطيرها.",
        ["Drag across words to strike them out."] = "اسحب عبر الكلمات لشطبها.",
        ["Click to add a comment."] = "انقر لإضافة تعليق.",
        ["Draw freehand."] = "ارسم بحرية.",
        ["Drag to draw a line."] = "اسحب لرسم خط.",
        ["Drag from the tail toward the arrowhead."] = "اسحب من ذيل السهم نحو رأسه.",
        ["Drag to draw a rectangle."] = "اسحب لرسم مستطيل.",
        ["Drag to draw an ellipse."] = "اسحب لرسم شكل بيضاوي.",
        ["Drag to paint a rectangle over the page. What it hides stays in the file: to remove it, use Redact."] = "اسحب لطلاء مستطيل فوق الصفحة. ما يخفيه يبقى في الملف: لإزالته استخدم الحجب.",
        ["Click where the picture goes."] = "انقر حيث توضع الصورة.",
        ["Click where your signature goes."] = "انقر حيث يوضع توقيعك.",
        ["Boxes show red until saved. Saving takes out everything under them for good, and they turn black."] = "تظهر المربعات حمراء حتى الحفظ. الحفظ يزيل كل ما تحتها نهائيًا، وتصبح سوداء.",
        ["Its author allows filling in this form and nothing else."] = "يسمح مؤلفه بتعبئة هذا النموذج فقط.",
        ["Its author allows filling in and comments, and nothing else."] = "يسمح مؤلفه بالتعبئة والتعليقات فقط.",
        ["This form is built with XFA, which can't be filled in here. You can still write on its pages."] = "هذا النموذج مبني بتقنية XFA التي لا يمكن تعبئتها هنا. لكن يمكنك الكتابة على صفحاته.",
        ["This PDF is signed: an edited copy no longer carries a valid signature."] = "هذا الملف موقّع: النسخة المعدّلة لا تحمل توقيعًا صالحًا.",
        ["This page has no text of its own: it is a picture. Use Write text and Whiteout instead."] = "هذه الصفحة لا نص فيها: إنها صورة. استخدم كتابة نص والطمس بالأبيض بدلًا من ذلك.",
        ["Couldn't search this PDF."] = "تعذّر البحث في هذا الملف.",
        ["{0} places marked"] = "موضع واحد مُعلَّم|موضعان مُعلَّمان|{0} مواضع مُعلَّمة|{0} موضعًا مُعلَّمًا|{0} موضع مُعلَّم",
        ["Saving PDF"] = "جارٍ حفظ PDF",
        ["{0} pages were redrawn as pictures to take out what was under their boxes."] = "أُعيد رسم صفحة واحدة كصورة لإزالة ما تحت مربعاتها.|أُعيد رسم صفحتين كصورتين لإزالة ما تحت مربعاتهما.|أُعيد رسم {0} صفحات كصور لإزالة ما تحت مربعاتها.|أُعيد رسم {0} صفحة كصور لإزالة ما تحت مربعاتها.|أُعيد رسم {0} صفحة كصور لإزالة ما تحت مربعاتها.",
        ["{0} retyped lines' old words couldn't be taken out: they are covered, but stay in the file."] = "تعذّر إخراج الكلمات القديمة من سطر واحد أُعيدت كتابته: إنها مغطاة لكنها تبقى في الملف.|تعذّر إخراج الكلمات القديمة من سطرين أُعيدت كتابتهما: إنها مغطاة لكنها تبقى في الملف.|تعذّر إخراج الكلمات القديمة من {0} أسطر أُعيدت كتابتها: إنها مغطاة لكنها تبقى في الملف.|تعذّر إخراج الكلمات القديمة من {0} سطرًا أُعيدت كتابتها: إنها مغطاة لكنها تبقى في الملف.|تعذّر إخراج الكلمات القديمة من {0} سطر أُعيدت كتابتها: إنها مغطاة لكنها تبقى في الملف.",
        ["Close without saving?"] = "إغلاق دون حفظ؟",
        ["Your changes to this PDF haven't been saved."] = "لم تُحفظ تغييراتك على هذا الملف.",
        ["Close without saving"] = "إغلاق دون حفظ",
        ["A page could not be redacted reliably, so nothing was saved."] = "تعذّر حجب إحدى الصفحات بشكل موثوق، فلم يُحفظ شيء.",
        ["Writing with {0}, on your own key…"] = "جارٍ الكتابة عبر {0} بمفتاحك…",
        ["Looking at the picture with {0}, on your own key…"] = "جارٍ فحص الصورة عبر {0} بمفتاحك…",
        ["Worked out by {0}, on your own key; it can be wrong."] = "أعدّه {0} بمفتاحك، وقد يخطئ.",
        ["Written by {0}, on your own key; check it before you publish it."] = "كتبه {0} بمفتاحك، فراجعه قبل نشره.",
        ["Ask anything about it: the answer comes from its own words, with where it says so. Your question and those words go to {0}, on your own key."] = "اسأل عن أي شيء فيه: تأتي الإجابة من كلماته هو، مع موضع قولها. ويُرسل سؤالك وتلك الكلمات إلى {0} بمفتاحك.",
        ["Translated by meaning, not word for word, by {0}, on your own key."] = "يترجم {0} بمفتاحك حسب المعنى لا كلمة بكلمة.",
        ["The words go to the AI you chose, on your own key; the voices and the rest happen on this PC. A video prepared once opens again at once."] = "تُرسل الكلمات إلى الذكاء الاصطناعي الذي اخترته بمفتاحك، أما الأصوات وبقية العمل فعلى هذا الحاسوب. والفيديو الذي جُهّز مرة يُفتح فورًا في المرة التالية.",
        ["Fast suits clear speech. Accurate is best for accents, noisy recordings and languages other than English."] = "السريع يناسب الكلام الواضح. والدقيق هو الأفضل للهجات والتسجيلات المشوشة واللغات غير الإنجليزية.",
        ["Speak, and DropWheel types what you say in any app, in whichever language you speak. It runs on this PC; nothing is sent anywhere."] = "تحدّث، فيكتب DropWheel ما تقوله في أي تطبيق، وبأي لغة تتحدث بها. يعمل على هذا الحاسوب ولا يُرسل شيئًا إلى أي مكان.",
        ["Accurate is best for accents and languages other than English; Fast suits clear English."] = "الدقيق هو الأفضل للهجات واللغات غير الإنجليزية، والسريع يناسب الإنجليزية الواضحة.",
        ["Translate Picture"] = "ترجمة صورة",
        ["A new picture is saved beside each original, with the language in its name."] = "تُحفظ صورة جديدة بجانب كل صورة أصلية، واسم اللغة في اسمها.",
        ["Reading the picture…"] = "جارٍ قراءة الصورة…",
        ["Windows has no reader for {0} on this PC, so some letters may be misread. Add the language under Settings › Time & language › Language."] = "لا يملك Windows قارئًا للغة {0} على هذا الجهاز، فقد يخطئ في قراءة بعض الحروف. أضف اللغة من الإعدادات › الوقت واللغة › اللغة.",
        ["Taking the text off…"] = "جارٍ إزالة النص…",
        ["Nothing here needed translating."] = "لا شيء هنا يحتاج إلى ترجمة.",
        ["Some of the text had to go smaller to fit: shorten it here if you like."] = "صُغّر بعض النص ليتّسع: يمكنك اختصاره هنا إن شئت.",
