        ["{0} × {1} mm, head {2} mm. This office states no head size: this is the usual one."] = "{0} × {1} مم، الرأس {2} مم. لا تذكر هذه الجهة حجمًا للرأس: هذا هو الحجم المعتاد.",
        ["{0} on a sheet."] = "{0} في الورقة.",
